#!/usr/bin/env bash
set -Eeuo pipefail

ZIP_NAME="QUANT_NOVA_2.4.21_RS_FIX_BUY_GATE_NXT_QUIET_ALERT_FINAL.zip"
ROOT_NAME="nova2421"
EXPECTED_ZIP_SHA256="b26c19ffca2ff561063947679f3353a992f5b2b57327173f9b5fc44d9d56c68c"
APP_DIR="$HOME/quant-nova"
IMAGE="quant-nova:2.4.21"
CONTAINER="quant-nova"
NETWORK="kiwoom-net"
HOST_PORT="3200"
TMP="$(mktemp -d)"
STAMP="$(date +%Y%m%d%H%M%S)"
BACKUP="${CONTAINER}-backup-${STAMP}"
OLD_RENAMED=0
NEW_STARTED=0

cleanup(){ rm -rf "$TMP"; }
fail(){ printf '\n[오류] %s\n' "$*" >&2; exit 1; }
say(){ printf '\n==> %s\n' "$*"; }
api_get(){
  local path="$1" max_time="${2:-6}" tries="${3:-12}" out="" i
  for i in $(seq 1 "$tries"); do
    if out="$(curl -fsS --connect-timeout 2 --max-time "$max_time" "http://127.0.0.1:${HOST_PORT}${path}" 2>/dev/null)" && [[ -n "$out" ]]; then
      printf '%s' "$out"
      return 0
    fi
    sleep 1
  done
  echo "[API 재시도 실패] ${path}" >&2
  return 1
}
build_image(){
  local attempt
  for attempt in 1 2; do
    echo "DOCKER_BUILD_ATTEMPT=${attempt}/2"
    if build_image || fail "Docker build 2회 모두 실패 — 기존 NOVA는 건드리지 않았습니다."; then return 0; fi
    echo "[경고] Docker build 실패 — transient network/cache 가능성, 1회 자동 재시도" >&2
    sleep 3
  done
  return 1
}
rollback(){
  local ec=$?
  [[ $ec -eq 0 ]] && return
  echo "[자동복구] NOVA 2.4.21 적용 실패 — 이전 NOVA 복구" >&2
  [[ $NEW_STARTED -eq 1 ]] && sudo docker rm -f "$CONTAINER" >/dev/null 2>&1 || true
  if [[ $OLD_RENAMED -eq 1 ]]; then
    sudo docker rename "$BACKUP" "$CONTAINER" >/dev/null 2>&1 || true
    sudo docker start "$CONTAINER" >/dev/null 2>&1 || true
  fi
}
trap cleanup EXIT
trap rollback ERR
[[ "$(id -u)" -ne 0 ]] || fail "ubuntu 사용자로 실행하세요."
echo "=== START QUANT NOVA 2.4.21 ONE-SHOT SAFE DEPLOY ==="

say "1/7 ONE-SHOT 사전점검 + Key/Secret/데이터 보존 확인"
for c in unzip python3 node curl docker sha256sum base64 awk df; do command -v "$c" >/dev/null 2>&1 || fail "필수 명령 없음: $c"; done
sudo docker info >/dev/null 2>&1 || fail "Docker daemon 접근 실패 — sudo docker info 확인 필요"
FREE_KB="$(df -Pk "$HOME" | awk 'NR==2{print $4}')"
[[ ${FREE_KB:-0} -ge 1048576 ]] || fail "디스크 여유 1GB 미만 — Docker build 전 공간 확보 필요"
OWNER_ID_PRE="$(sudo docker ps -q --filter publish=${HOST_PORT} | head -n1 || true)"
if [[ -n "$OWNER_ID_PRE" ]]; then
  OWNER_NAME_PRE="$(sudo docker inspect "$OWNER_ID_PRE" --format '{{.Name}}' | sed 's#^/##')"
  [[ "$OWNER_NAME_PRE" == "$CONTAINER" ]] || fail "포트 ${HOST_PORT}을 다른 컨테이너 ${OWNER_NAME_PRE}가 사용 중 — 안전상 중단"
fi
[[ -s "$APP_DIR/.env" ]] || fail "$APP_DIR/.env 없음 — 기존 Key/Secret 보존 환경을 찾지 못했습니다."
KEYLEN="$(sed -n 's/^KIWOOM_APP_KEY=//p' "$APP_DIR/.env" | tail -n1 | awk '{print length}')"
SECLEN="$(sed -n -e 's/^KIWOOM_APP_SECRET=//p' -e 's/^KIWOOM_SECRET_KEY=//p' "$APP_DIR/.env" | tail -n1 | awk '{print length}')"
[[ ${KEYLEN:-0} -gt 5 && ${SECLEN:-0} -gt 5 ]] || fail "Key/Secret 값 확인 실패"
mkdir -p "$APP_DIR/data"; chmod 700 "$APP_DIR/data"
# Source repository privacy and runtime API protection are separate. Generate a write-only API token if absent.
ACCESS_TOKEN_CREATED=0
ACCESS_TOKEN_VALUE="$(sed -n 's/^APP_ACCESS_TOKEN=//p' "$APP_DIR/.env" | tail -n1)"
if [[ -z "$ACCESS_TOKEN_VALUE" ]]; then
  command -v python3 >/dev/null 2>&1 || fail "APP_ACCESS_TOKEN 생성에 python3 필요"
  ACCESS_TOKEN_VALUE="$(python3 -c 'import secrets; print(secrets.token_urlsafe(32))')"
  printf '\nAPP_ACCESS_TOKEN=%s\n' "$ACCESS_TOKEN_VALUE" >> "$APP_DIR/.env"
  chmod 600 "$APP_DIR/.env"
  ACCESS_TOKEN_CREATED=1
fi
echo "KEY_SECRET=OK (values hidden)"
echo "WRITE_API_GUARD=ENABLED (token value hidden)"
echo "DATA_DIR=$APP_DIR/data"

say "2/7 NOVA 2.4.21 EMBEDDED SOURCE 복원 + SHA/manifest 검증"
echo "SOURCE=EMBEDDED_IN_INSTALLER (GitHub ZIP 별도 다운로드 없음)"
