[[ -s "$TMP/$ZIP_NAME" ]] || fail "내장 ZIP 복원 실패"
ACTUAL_SHA="$(sha256sum "$TMP/$ZIP_NAME" | awk '{print $1}')"
[[ "$ACTUAL_SHA" == "$EXPECTED_ZIP_SHA256" ]] || fail "내장 ZIP SHA256 불일치: 예상=$EXPECTED_ZIP_SHA256 실제=$ACTUAL_SHA"
echo "ZIP_SHA256=OK $ACTUAL_SHA"
unzip -q "$TMP/$ZIP_NAME" -d "$TMP/src"
ROOT="$TMP/src/$ROOT_NAME"
[[ -f "$ROOT/Dockerfile" && -f "$ROOT/app/main.py" && -f "$ROOT/app/evidence_engine.py" && -f "$ROOT/app/archive_engine.py" && -f "$ROOT/app/shadow_engine.py" && -f "$ROOT/app/rs_shadow_engine.py" && -f "$ROOT/config/live_parity_2.4.13.json" && -f "$ROOT/static/nova.js" && -f "$ROOT/config/krx_holidays.json" && -f "$ROOT/scripts/replay_backtest.py" && -f "$ROOT/scripts/selfcheck.py" && -f "$ROOT/SOURCE_MANIFEST.sha256" ]] || fail "ZIP 내부 구조 오류"
(cd "$ROOT" && sha256sum -c SOURCE_MANIFEST.sha256 >/dev/null) || fail "SOURCE_MANIFEST 무결성 검사 실패"

say "3/7 정적 사전검증 — full selfcheck는 Docker 내부에서 requirements 설치 후 실행"
python3 -m py_compile "$ROOT/app/main.py" "$ROOT/app/evidence_engine.py" "$ROOT/app/archive_engine.py" "$ROOT/app/shadow_engine.py" "$ROOT/app/rs_shadow_engine.py" "$ROOT/scripts/replay_backtest.py" "$ROOT/scripts/selfcheck.py"
